package os.aios.core.indexing;
import android.content.*;
import android.database.*;
import android.database.sqlite.*;
import org.json.*;

/** Rebuildable per-source/operator ledger; scheduling truth stays in AutomationStore. */
public final class PhotoIndexStore extends SQLiteOpenHelper {
    public PhotoIndexStore(Context c){this(c,"aios_photo_index.db");}
    public PhotoIndexStore(Context c,String name){super(c,name,null,2);setWriteAheadLoggingEnabled(true);}
    public void onCreate(SQLiteDatabase d){
        d.execSQL("CREATE TABLE photos(id INTEGER PRIMARY KEY,identity TEXT UNIQUE NOT NULL,source_version TEXT NOT NULL,source_json TEXT NOT NULL,visible INTEGER NOT NULL DEFAULT 1,space_id TEXT NOT NULL DEFAULT '',embedding_state TEXT NOT NULL DEFAULT 'pending',face_state TEXT NOT NULL DEFAULT 'pending',exif_state TEXT NOT NULL DEFAULT 'pending',face_json TEXT,exif_json TEXT,error TEXT NOT NULL DEFAULT '',seen INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL)");
        d.execSQL("CREATE INDEX photo_pending ON photos(visible,embedding_state,face_state,exif_state)");
        d.execSQL("CREATE TABLE discovery(id INTEGER PRIMARY KEY CHECK(id=1),after_id INTEGER NOT NULL DEFAULT 0,cycle INTEGER NOT NULL DEFAULT 1,complete INTEGER NOT NULL DEFAULT 0)");d.execSQL("INSERT INTO discovery(id) VALUES(1)");generationSchema(d);
    }
    public void onUpgrade(SQLiteDatabase d,int old,int next){if(old==1&&next==2)generationSchema(d);else throw new IllegalStateException("Unsupported photo schema migration");}
    private static final String SNAPSHOT_COLUMNS="id,identity,source_version,source_json,visible,space_id,embedding_state,face_state,exif_state,face_json,exif_json,error,updated_at";
    private void generationSchema(SQLiteDatabase d){d.execSQL("CREATE TABLE embedding_profiles(space_id TEXT PRIMARY KEY,manifest TEXT NOT NULL,created_at INTEGER NOT NULL)");d.execSQL("CREATE TABLE index_generations(id INTEGER PRIMARY KEY,space_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('active','staging','retired')),created_at INTEGER NOT NULL,published_at INTEGER)");d.execSQL("CREATE UNIQUE INDEX one_active_generation ON index_generations(state) WHERE state='active'");d.execSQL("CREATE TABLE photo_snapshots(generation INTEGER NOT NULL,id INTEGER NOT NULL,identity TEXT,source_version TEXT,source_json TEXT,visible INTEGER,space_id TEXT,embedding_state TEXT,face_state TEXT,exif_state TEXT,face_json TEXT,exif_json TEXT,error TEXT,updated_at INTEGER,PRIMARY KEY(generation,id))");d.execSQL("CREATE INDEX snapshot_camera ON photo_snapshots(generation,json_extract(exif_json,'$.fields.camera_model'))");d.execSQL("CREATE INDEX snapshot_faces ON photo_snapshots(generation,face_state,json_extract(face_json,'$.detected_count'))");}
    public synchronized void prepare(JSONObject manifest)throws Exception{String space=manifest.getString("space_id");if(!space.matches("[a-f0-9]{64}"))throw new IllegalArgumentException("Invalid embedding profile");SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{d.execSQL("INSERT OR IGNORE INTO embedding_profiles VALUES(?,?,?)",new Object[]{space,manifest.toString(),System.currentTimeMillis()});if(one("SELECT id FROM index_generations LIMIT 1")==null){JSONObject prior=one("SELECT space_id,count(*) AS n FROM photos WHERE space_id<>'' GROUP BY space_id ORDER BY n DESC LIMIT 1");String legacy=prior==null?space:prior.getString("space_id");d.execSQL("INSERT INTO index_generations VALUES(0,?,'active',?,?)",new Object[]{legacy,System.currentTimeMillis(),System.currentTimeMillis()});d.execSQL("INSERT OR REPLACE INTO photo_snapshots(generation,"+SNAPSHOT_COLUMNS+") SELECT 0,"+SNAPSHOT_COLUMNS+" FROM photos WHERE space_id=?",new Object[]{legacy});}if(one("SELECT id FROM index_generations WHERE space_id=? AND state IN ('active','staging')",space)==null){d.execSQL("UPDATE index_generations SET state='retired' WHERE state='staging'");d.execSQL("INSERT INTO index_generations(space_id,state,created_at) VALUES(?,'staging',?)",new Object[]{space,System.currentTimeMillis()});}d.setTransactionSuccessful();}finally{d.endTransaction();}}
    public synchronized JSONObject activeGeneration()throws Exception{return one("SELECT * FROM index_generations WHERE state='active'");}
    public synchronized JSONArray generations()throws Exception{return rows("SELECT * FROM index_generations ORDER BY id");}
    public synchronized long generationFor(String space)throws Exception{JSONObject row=one("SELECT id FROM index_generations WHERE space_id=? AND state IN ('active','staging') ORDER BY id DESC LIMIT 1",space);if(row==null)throw new IllegalStateException("Profile not registered");return row.getLong("id");}
    public synchronized boolean publishGeneration(String space,long vectorCount)throws Exception{SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{long generation=generationFor(space);JSONObject target=one("SELECT * FROM index_generations WHERE id=?",Long.toString(generation));JSONObject progress=progress();if(!target.getString("state").equals("staging")||!progress.getBoolean("inventory_complete")||progress.optInt("pending")>0||progress.optInt("failed")>0||progress.optInt("cleanup_pending")>0)return false;long expected=one("SELECT count(*) AS n FROM photos WHERE visible=1 AND space_id=? AND embedding_state='ready'",space).getLong("n");long snapshots=one("SELECT count(*) AS n FROM photo_snapshots WHERE generation=? AND visible=1",Long.toString(generation)).getLong("n");long visible=one("SELECT count(*) AS n FROM photos WHERE visible=1").getLong("n");if(vectorCount!=expected||snapshots!=visible)throw new IllegalStateException("generation_integrity_mismatch");d.execSQL("UPDATE index_generations SET state='retired' WHERE state='active'");d.execSQL("UPDATE index_generations SET state='active',published_at=? WHERE id=?",new Object[]{System.currentTimeMillis(),generation});d.setTransactionSuccessful();return true;}finally{d.endTransaction();}}
    private void snapshot(long id)throws Exception{JSONObject photo=one("SELECT space_id FROM photos WHERE id=?",Long.toString(id));if(photo==null||photo.optString("space_id").isEmpty())return;long generation=generationFor(photo.getString("space_id"));getWritableDatabase().execSQL("INSERT OR REPLACE INTO photo_snapshots(generation,"+SNAPSHOT_COLUMNS+") SELECT ?,"+SNAPSHOT_COLUMNS+" FROM photos WHERE id=?",new Object[]{generation,id});}
    public synchronized JSONObject discovery()throws Exception{return one("SELECT * FROM discovery WHERE id=1");}
    public synchronized void discover(JSONArray items,boolean more,long after)throws Exception{
        SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{long cycle=discovery().getLong("cycle");for(int i=0;i<items.length();i++){
            JSONObject item=items.getJSONObject(i);String identity=(android.os.Process.myUid()/100000)+":"+item.getJSONObject("fields").optString("volume_name")+":"+item.optString("database_version")+":"+item.getString("id");
            JSONObject old=one("SELECT * FROM photos WHERE identity=?",identity);String version=item.getString("source_version");ContentValues v=new ContentValues();v.put("identity",identity);v.put("source_version",version);v.put("source_json",item.toString());v.put("visible",1);v.put("seen",cycle);v.put("updated_at",System.currentTimeMillis());
            if(old==null)d.insertOrThrow("photos",null,v);else{if(!version.equals(old.getString("source_version"))){v.put("embedding_state","pending");v.put("face_state","pending");v.put("exif_state","pending");v.putNull("face_json");v.putNull("exif_json");}d.update("photos",v,"identity=?",new String[]{identity});}
        }
        d.execSQL("UPDATE discovery SET after_id=?,complete=? WHERE id=1",new Object[]{more?after:0,more?0:1});if(!more){d.execSQL("UPDATE photos SET visible=0 WHERE seen<>?",new Object[]{cycle});d.execSQL("UPDATE discovery SET cycle=cycle+1 WHERE id=1");}d.setTransactionSuccessful();}finally{d.endTransaction();}
    }
    public synchronized JSONArray pending(String space,int limit)throws Exception{
        getWritableDatabase().execSQL("UPDATE photos SET embedding_state='pending',face_state='pending',face_json=NULL,space_id=? WHERE space_id<>?",new Object[]{space,space});
        return rows("SELECT * FROM photos WHERE visible=1 AND (embedding_state='pending' OR face_state='pending' OR exif_state='pending') ORDER BY id LIMIT ?",Integer.toString(limit));
    }
    public synchronized void publish(long id,String version,String operator,String state,JSONObject data)throws Exception{
        if(!java.util.Set.of("embedding","face","exif").contains(operator))throw new IllegalArgumentException("Unknown operator");ContentValues v=new ContentValues();v.put(operator+"_state",state);v.put("updated_at",System.currentTimeMillis());if(state.equals("failed")&&data!=null)v.put("error",operator+": "+data.optString("error","processing_failed"));if(!operator.equals("embedding"))v.put(operator+"_json",data==null?null:data.toString());
        SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{if(d.update("photos",v,"id=? AND source_version=? AND visible=1",new String[]{Long.toString(id),version})!=1)throw new IllegalStateException("stale_photo_result");snapshot(id);d.setTransactionSuccessful();}finally{d.endTransaction();}
    }
    public synchronized JSONObject metadataFor(JSONObject source)throws Exception{JSONObject active=activeGeneration();if(active==null)return null;return one("SELECT * FROM photo_snapshots WHERE generation=? AND visible=1 AND source_version=? AND json_extract(source_json,'$.id')=? AND json_extract(source_json,'$.database_version')=?",active.getString("id"),source.getString("source_version"),source.getString("id"),source.optString("database_version"));}
    public synchronized JSONObject photo(long id)throws Exception{return one("SELECT * FROM photos WHERE id=? AND visible=1",Long.toString(id));}
    public synchronized JSONObject photo(long id,long generation)throws Exception{return one("SELECT * FROM photo_snapshots WHERE id=? AND generation=? AND visible=1 AND EXISTS(SELECT 1 FROM photos live WHERE live.id=photo_snapshots.id AND live.visible=1)",Long.toString(id),Long.toString(generation));}
    public synchronized JSONArray invisible(int limit)throws Exception{return rows("SELECT id,space_id FROM photos WHERE visible=0 ORDER BY id LIMIT ?",Integer.toString(limit));}
    public synchronized void forgetInvisible(long id){getWritableDatabase().delete("photo_snapshots","id=? AND EXISTS(SELECT 1 FROM photos p WHERE p.id=photo_snapshots.id AND p.visible=0)",new String[]{Long.toString(id)});getWritableDatabase().delete("photos","id=? AND visible=0",new String[]{Long.toString(id)});}
    public synchronized void retryUnavailableFaces(){getWritableDatabase().execSQL("UPDATE photos SET face_state='pending' WHERE visible=1 AND face_state='model_unavailable'");}
    public synchronized void retryFailed(){getWritableDatabase().execSQL("UPDATE photos SET embedding_state=CASE WHEN embedding_state='failed' THEN 'pending' ELSE embedding_state END,face_state=CASE WHEN face_state='failed' THEN 'pending' ELSE face_state END,exif_state=CASE WHEN exif_state='failed' THEN 'pending' ELSE exif_state END WHERE visible=1");}
    public synchronized void invalidate(long id){getWritableDatabase().execSQL("UPDATE photos SET visible=0 WHERE id=?",new Object[]{id});}
    public synchronized boolean coverageComplete()throws Exception{JSONObject p=progress();return p.optBoolean("inventory_complete")&&p.optInt("pending")==0&&p.optInt("failed")==0&&p.optInt("cleanup_pending")==0&&p.optInt("faces_unavailable")==0;}
    public synchronized JSONObject progress()throws Exception{
        JSONObject result=one("SELECT count(*) AS discovered,sum(CASE WHEN embedding_state='ready' THEN 1 ELSE 0 END) AS indexed,sum(CASE WHEN face_state='ready' THEN 1 ELSE 0 END) AS faces_processed,sum(CASE WHEN face_state='model_unavailable' THEN 1 ELSE 0 END) AS faces_unavailable,sum(CASE WHEN exif_state IN ('ready','no_metadata') THEN 1 ELSE 0 END) AS exif_processed,sum(CASE WHEN embedding_state='pending' OR face_state='pending' OR exif_state='pending' THEN 1 ELSE 0 END) AS pending,sum(CASE WHEN embedding_state='failed' OR face_state='failed' OR exif_state='failed' THEN 1 ELSE 0 END) AS failed,max(updated_at) AS last_processed_at FROM photos WHERE visible=1");return result.put("inventory_complete",discovery().optInt("complete")==1).put("cleanup_pending",one("SELECT count(*) AS n FROM photos WHERE visible=0").getInt("n")).put("active_generation",activeGeneration()).put("staging_generation",one("SELECT * FROM index_generations WHERE state='staging'"));
    }
    public synchronized JSONArray metadataCandidates(int offset,int limit)throws Exception{return rows("SELECT * FROM photos WHERE visible=1 ORDER BY id LIMIT ? OFFSET ?",Integer.toString(limit),Integer.toString(offset));}
    /** Parameterized local prefilter; every surviving result still rechecks the live Provider. */
    public synchronized JSONArray metadataCandidates(int offset,int limit,JSONObject filters,long generation)throws Exception{
        StringBuilder where=new StringBuilder("visible=1 AND generation=? AND EXISTS(SELECT 1 FROM photos live WHERE live.id=photo_snapshots.id AND live.visible=1)");java.util.ArrayList<String> args=new java.util.ArrayList<>();args.add(Long.toString(generation));
        if(filters!=null){for(String key:java.util.List.of("from_ms","to_ms"))if(filters.has(key)){where.append(" AND json_extract(source_json,'$.time_ms')").append(key.equals("from_ms")?">=":"<").append("CAST(? AS REAL)");args.add(filters.getString(key));}
            JSONObject faces=filters.optJSONObject("faces");if(faces!=null){where.append(" AND face_state='ready'");String count="json_extract(face_json,'$.detected_count')";if(faces.has("present"))where.append(" AND ").append(count).append(faces.getBoolean("present")?">0":"=0");for(String key:java.util.List.of("detected_count_min","detected_count_max"))if(faces.has(key)){where.append(" AND ").append(count).append(key.endsWith("min")?">=":"<=").append("CAST(? AS REAL)");args.add(faces.getString(key));}}
            JSONObject photo=filters.optJSONObject("photo");if(photo!=null){java.util.Iterator<String> keys=photo.keys();while(keys.hasNext()){String key=keys.next();if(java.util.Set.of("camera_make","camera_model","lens_model").contains(key)){where.append(" AND lower(json_extract(exif_json,'$.fields.").append(key).append("'))=lower(?)");args.add(photo.getString(key));}else if(key.equals("gps_bbox")){JSONArray bounds=photo.getJSONArray(key);String[] fields={"longitude","latitude","longitude","latitude"};for(int n=0;n<4;n++){where.append(" AND json_extract(exif_json,'$.fields.").append(fields[n]).append("')").append(n<2?">=":"<=").append("CAST(? AS REAL)");args.add(bounds.getString(n));}}else if(java.util.Set.of("taken_time","iso","f_number","exposure_seconds","focal_length_mm").contains(key)){JSONObject range=photo.getJSONObject(key);String field=key.equals("taken_time")?(range.getString("field").equals("media_taken")?"json_extract(source_json,'$.time_ms')":"json_extract(exif_json,'$.fields.taken_at_ms')"):"json_extract(exif_json,'$.fields."+key+"')";for(String bound:java.util.List.of("min","max"))if(range.has(bound)){where.append(" AND ").append(field).append(bound.equals("min")?">=":"<=").append("CAST(? AS REAL)");args.add(range.getString(bound));}}else throw new IllegalArgumentException("Unsupported metadata filter");}}
        }
        args.add(Integer.toString(limit));args.add(Integer.toString(offset));return rows("SELECT * FROM photo_snapshots WHERE "+where+" ORDER BY id LIMIT ? OFFSET ?",args.toArray(new String[0]));
    }
    private JSONObject one(String sql,String...args)throws Exception{JSONArray a=rows(sql,args);return a.length()==0?null:a.getJSONObject(0);}
    private JSONArray rows(String sql,String...args)throws Exception{JSONArray out=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery(sql,args)){while(c.moveToNext()){JSONObject row=new JSONObject();for(int i=0;i<c.getColumnCount();i++)row.put(c.getColumnName(i),c.isNull(i)?JSONObject.NULL:c.getType(i)==Cursor.FIELD_TYPE_INTEGER?c.getLong(i):c.getString(i));out.put(row);}}return out;}
}
